// @FIGURE_CODE_BEGIN
(function () {
  var PI = Math.PI;
  var NAVY = '#1b3a63', BLUE = '#2e74b5', ORANGE = '#e8792a', TEAL = '#18988c',
      GRAYC = '#bdbdbd', GRAYF = '#d0d0d0', GRAYAX = '#a8a8a8', BLACK = '#000';

  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  var W = 710, H = 320;
  draw.viewbox(0, 0, W, H);
  draw.rect(W, H).fill('#ffffff');

  // ---- shared vertical scale: circle radius R  ==  y = 1 on the graph ----
  var CCX = 120, CCY = 165, R = 68;
  var GX0 = 290, GY0 = 165, SX = 60, SY = 68;

  function gX(x) { return GX0 + x * SX; }
  function gY(y) { return GY0 - y * SY; }
  function cX(u) { return CCX + u * R; }
  function cY(v) { return CCY - v * R; }

  var st = draw.group();   // static geometry
  var dyn = draw.group();  // moving parts

  var state = { angle: 0.524, full: false, sweeping: false };

  // ---------- helpers ----------
  function txt(g, s, x, y, o) {
    o = o || {};
    var t = g.plain(s);
    t.font({
      family: o.family || 'Georgia, "Times New Roman", serif',
      size: o.size || 11,
      anchor: o.anchor || 'middle',
      style: o.italic ? 'italic' : 'normal',
      weight: o.weight || 'normal'
    });
    t.fill(o.color || BLACK);
    t.attr({ x: x, y: y });
    if (o.halo !== false) {
      t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': (o.haloW || 3), 'stroke-linejoin': 'round' });
    }
    return t;
  }

  function head(g, x, y, ang, size, color) {
    var p = [
      [x, y],
      [x - size * Math.cos(ang - 0.42), y - size * Math.sin(ang - 0.42)],
      [x - size * Math.cos(ang + 0.42), y - size * Math.sin(ang + 0.42)]
    ];
    return g.polygon(p).fill(color).stroke('none');
  }

  function dblArrow(g, x1, y1, x2, y2, color, w, sz) {
    w = w || 1.2; sz = sz || 6;
    g.line(x1, y1, x2, y2).stroke({ color: color, width: w, linecap: 'round' });
    var a = Math.atan2(y2 - y1, x2 - x1);
    head(g, x2, y2, a, sz, color);
    head(g, x1, y1, a + PI, sz, color);
  }

  function frac(g, x, yBase, num, den, size, color) {
