// @FIGURE_CODE_BEGIN
(function () {
  var PI = Math.PI;
  var NAVY = '#1b3a63', BLUE = '#2e74b5', ORANGE = '#e8792a', TEAL = '#18988c',
      GRAYC = '#bdbdbd', GRAYF = '#d0d0d0', GRAYAX = '#a8a8a8', BLACK = '#000';

  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  var W = 710, H = 320;
  draw.viewbox(0, 0, W, H);
  draw.rect(W, H).fill('#ffffff');

  // ---- shared vertical scale: circle radius R  ==  y = 1 on the graph ----
  var CCX = 120, CCY = 165, R = 68;
  var GX0 = 290, GY0 = 165, SX = 60, SY = 68;

  function gX(x) { return GX0 + x * SX; }
  function gY(y) { return GY0 - y * SY; }
  function cX(u) { return CCX + u * R; }
  function cY(v) { return CCY - v * R; }

  var st = draw.group();   // static geometry
  var dyn = draw.group();  // moving parts

  var state = { angle: 0.524, full: false, sweeping: false };

  // ---------- helpers ----------
  function txt(g, s, x, y, o) {
    o = o || {};
    var t = g.plain(s);
    t.font({
      family: o.family || 'Georgia, "Times New Roman", serif',
      size: o.size || 11,
      anchor: o.anchor || 'middle',
      style: o.italic ? 'italic' : 'normal',
      weight: o.weight || 'normal'
    });
    t.fill(o.color || BLACK);
    t.attr({ x: x, y: y });
    if (o.halo !== false) {
      t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': (o.haloW || 3), 'stroke-linejoin': 'round' });
    }
    return t;
  }

  function head(g, x, y, ang, size, color) {
    var p = [
      [x, y],
      [x - size * Math.cos(ang - 0.42), y - size * Math.sin(ang - 0.42)],
      [x - size * Math.cos(ang + 0.42), y - size * Math.sin(ang + 0.42)]
    ];
    return g.polygon(p).fill(color).stroke('none');
  }

  function dblArrow(g, x1, y1, x2, y2, color, w, sz) {
    w = w || 1.2; sz = sz || 6;
    g.line(x1, y1, x2, y2).stroke({ color: color, width: w, linecap: 'round' });
    var a = Math.atan2(y2 - y1, x2 - x1);
    head(g, x2, y2, a, sz, color);
    head(g, x1, y1, a + PI, sz, color);
  }

  function frac(g, x, yBase, num, den, size, color) {
    if (den === null) { txt(g, num, x, yBase + 6, { size: size, color: color }); return; }
    txt(g, num, x, yBase, { size: size, color: color });
    g.line(x - 5.5, yBase + 3, x + 5.5, yBase + 3).stroke({ color: color, width: 0.9 });
    txt(g, den, x, yBase + 14, { size: size, color: color });
  }

  function gcd(a, b) { return b ? gcd(b, a % b) : a; }
  function piFrac(a) {
    var n = Math.round(a / (PI / 12));
    if (Math.abs(a - n * PI / 12) > 0.02) return null;
    if (n === 0) return '0';
    var g = gcd(n, 12), num = n / g, den = 12 / g;
    var s = (num === 1 ? 'π' : num + 'π');
    return den === 1 ? s : s + '/' + den;
  }

  function curveDomain() { return state.full ? [-0.35, 2 * PI + 0.35] : [-0.55, 2.65]; }

  function sinePts(a, b, n) {
    var pts = [], i, x;
    n = n || 260;
    for (i = 0; i <= n; i++) { x = a + (b - a) * i / n; pts.push([gX(x), gY(Math.sin(x))]); }
    return pts;
  }

  // ---------- static drawing ----------
  function drawStatic() {
    st.clear();

    // ===== LEFT PANEL : unit circle =====
    dblArrow(st, 20, CCY, 228, CCY, GRAYAX, 1.2, 6);
    dblArrow(st, CCX, 70, CCX, 262, GRAYAX, 1.2, 6);

    [30, 45, 60, 120, 135, 150].forEach(function (d) {
      var a = d * PI / 180;
      st.line(cX(Math.cos(a)), cY(Math.sin(a)), cX(-Math.cos(a)), cY(-Math.sin(a)))
        .stroke({ color: GRAYF, width: 1 });
    });

    var circ = st.circle(2 * R).center(CCX, CCY).fill('none').stroke({ color: GRAYC, width: 1.5 });
    circ.css('cursor', 'pointer');
    circ.on('mousemove', function (e) { showTooltip('Unit circle: every point is (cos x, sin x)', e); })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('The unit circle',
            'A circle of radius 1 centred at the origin. If you rotate by an angle x from the positive horizontal axis, the point you land on has coordinates (cos x, sin x). Its height above the horizontal axis IS sin x.');
        });

    // ===== RIGHT PANEL : axes =====
    dblArrow(st, 245, GY0, 690, GY0, BLACK, 1.4, 7);           // x axis
    st.line(GX0, 58, GX0, 272).stroke({ color: BLACK, width: 1.4 });
    head(st, GX0, 55, -PI / 2, 7, BLACK);                      // y axis arrow
    txt(st, 'y', GX0 + 12, 52, { size: 16, italic: true, weight: 'bold' });
    txt(st, 'x', 702, 160, { size: 16, italic: true, weight: 'bold' });

    // y ticks
    st.line(GX0 - 4, gY(1), GX0 + 4, gY(1)).stroke({ color: BLACK, width: 1.2 });
    st.line(GX0 - 4, gY(-1), GX0 + 4, gY(-1)).stroke({ color: BLACK, width: 1.2 });
    txt(st, '1', GX0 - 11, gY(1) + 4, { size: 12, anchor: 'end' });
    txt(st, '-1', GX0 - 11, gY(-1) + 4, { size: 12, anchor: 'end' });
    txt(st, '0', GX0 - 11, GY0 + 16, { size: 12, anchor: 'end' });

    // x ticks depend on mode
    var ticks = state.full
      ? [{ v: PI / 2, n: 'π', d: '2' }, { v: PI, n: 'π', d: null },
         { v: 3 * PI / 2, n: '3π', d: '2' }, { v: 2 * PI, n: '2π', d: null }]
      : [{ v: PI / 6, n: 'π', d: '6' }, { v: PI / 4, n: 'π', d: '4' },
         { v: PI / 3, n: 'π', d: '3' }, { v: PI / 2, n: 'π', d: '2' }];

    ticks.forEach(function (t) {
      var x = gX(t.v);
      st.line(x, GY0 - 4, x, GY0 + 4).stroke({ color: BLACK, width: 1.1 });
      frac(st, x, 184, t.n, t.d, 10, BLACK);
    });

    // orange dashed drops from curve to the labelled ticks
    ticks.forEach(function (t) {
      var s = Math.sin(t.v);
      if (Math.abs(s) < 0.06) return;
      var x = gX(t.v);
      var ln = st.line(x, gY(s), x, GY0).stroke({ color: ORANGE, width: 1.3, dasharray: '4,3' });
      ln.css('cursor', 'pointer');
      ln.on('mousemove', function (e) { showTooltip('sin(' + (piFrac(t.v) || t.v.toFixed(2)) + ') = ' + s.toFixed(3), e); })
        .on('mouseleave', hideTooltip);
    });

    // teal dashed horizontals: curve height  ←→  circle height
    var tealAngles = [PI / 6, PI / 4, PI / 3, PI / 2];
    tealAngles.forEach(function (a) {
      var s = Math.sin(a), c = Math.cos(a);
      var y = gY(s);
      var ln = st.line(cX(c), y, gX(a), y).stroke({ color: TEAL, width: 1.3, dasharray: '5,4' });
      st.circle(3.2).center(cX(c), cY(s)).fill(TEAL).opacity(0.75);
      ln.css('cursor', 'pointer');
      ln.on('mousemove', function (e) {
        showTooltip('Height ' + s.toFixed(3) + ' on the circle = height of the curve at x = ' + (piFrac(a) || a.toFixed(2)), e);
      }).on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('Carrying the height across',
            'This teal line transports the circle point&rsquo;s vertical height straight across to the graph. The sine curve sits at exactly that height above the matching angle on the x-axis — the two pictures record the same number.');
        });
    });

    // ===== sine curve =====
    var dm = curveDomain();
    var pts = sinePts(dm[0], dm[1]);
    var curve = st.polyline(pts).fill('none')
      .stroke({ color: NAVY, width: 3, linecap: 'round', linejoin: 'round' });
    var p0 = pts[0], p1 = pts[1], pn = pts[pts.length - 1], pm = pts[pts.length - 2];
    head(st, p0[0], p0[1], Math.atan2(p0[1] - p1[1], p0[0] - p1[0]), 8, NAVY);
    head(st, pn[0], pn[1], Math.atan2(pn[1] - pm[1], pn[0] - pm[0]), 8, NAVY);
    curve.css('cursor', 'pointer');
    curve.on('mousemove', function (e) { showTooltip('y = sin(x): the circle point&rsquo;s height, plotted against the angle', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('y = sin(x)',
          'Sweep the angle x around the unit circle and record, at each moment, how high the point is. Plotting that height against x traces this curve: zero at x = 0, a maximum of 1 at x = π/2, back to zero at π, and negative through the third and fourth quadrants.');
      });

    txt(st, 'y = sin(x)', 472, 72, { size: 15, color: BLUE, italic: true, weight: 'bold' });
  }

  // ---------- dynamic drawing ----------
  function drawDynamic() {
    dyn.clear();
    var a = state.angle, s = Math.sin(a), c = Math.cos(a);
    var dm = curveDomain();

    // swept sector on the circle
    var large = (a > PI) ? 1 : 0;
    if (a > 0.001) {
      dyn.path('M ' + CCX + ',' + CCY + ' L ' + cX(1) + ',' + cY(0) +
        ' A ' + R + ',' + R + ' 0 ' + large + ' 0 ' + cX(c) + ',' + cY(s) + ' Z')
        .fill({ color: s >= 0 ? BLUE : ORANGE, opacity: 0.10 }).stroke('none');
      // traced arc
      dyn.path('M ' + cX(1) + ',' + cY(0) + ' A ' + R + ',' + R + ' 0 ' + large + ' 0 ' + cX(c) + ',' + cY(s))
        .fill('none').stroke({ color: BLUE, width: 2.4, opacity: 0.55, linecap: 'round' });
    }

    // active radius + drop line + point
    dyn.line(CCX, CCY, cX(c), cY(s)).stroke({ color: NAVY, width: 2.6, linecap: 'round' });
    dyn.line(cX(c), cY(s), cX(c), CCY).stroke({ color: NAVY, width: 1, dasharray: '3,3' });
    var pt = dyn.circle(7).center(cX(c), cY(s)).fill(NAVY);
    pt.css('cursor', 'pointer');
    pt.on('mousemove', function (e) {
      showTooltip('(cos x, sin x) = (' + c.toFixed(2) + ', ' + s.toFixed(2) + ')', e);
    }).on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('The circle point',
          'Its horizontal coordinate is cos x and its vertical coordinate is sin x. Only the vertical one — the height — is what the sine graph records.');
      });

    // traced portion of the curve (the "record written so far")
    var aClip = Math.min(a, dm[1]);
    if (aClip > 0.01) {
      dyn.polyline(sinePts(0, aClip, 200)).fill('none')
        .stroke({ color: BLUE, width: 4.2, opacity: 0.45, linecap: 'round', linejoin: 'round' });
    }

    // teal connector + tracer on the graph
    if (a >= dm[0] && a <= dm[1]) {
      var tl = dyn.line(cX(c), gY(s), gX(a), gY(s))
        .stroke({ color: TEAL, width: 1.9, dasharray: '6,4' });
      tl.css('cursor', 'pointer');
      tl.on('mousemove', function (e) { showTooltip('Same height on both pictures: ' + s.toFixed(3), e); })
        .on('mouseleave', hideTooltip);
      dyn.line(gX(a), gY(s), gX(a), GY0).stroke({ color: NAVY, width: 1, dasharray: '3,3' });
      var tr = dyn.circle(8).center(gX(a), gY(s)).fill(NAVY).stroke({ color: '#fff', width: 1.2 });
      tr.css('cursor', 'pointer');
      tr.on('mousemove', function (e) {
        showTooltip('(x, sin x) = (' + a.toFixed(2) + ', ' + s.toFixed(2) + ')', e);
      }).on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('The graph point',
            'Its horizontal position is the angle x and its vertical position is the height of the circle point. Move the slider and watch both dots rise and fall together.');
        });
    }

    // readout
    var f = piFrac(a);
    txt(dyn, 'x = ' + a.toFixed(2) + ' rad' + (f ? '   (' + f + ')' : ''), 14, 24,
      { size: 12, anchor: 'start', color: NAVY, family: 'sans-serif' });
    txt(dyn, 'sin(x) = height = ' + (s >= 0 ? ' ' : '') + s.toFixed(3), 14, 40,
      { size: 12, anchor: 'start', color: TEAL, family: 'sans-serif' });
  }

  // ---------- controls ----------
  function setAngle(v, fromUI) {
    state.angle = v;
    var inp = document.getElementById('angleInput');
    var out = document.getElementById('angleVal');
    if (inp && !fromUI) inp.value = v;
    if (out) out.value = (+v).toFixed(2);
    if (v > 2.6 && !state.full) {
      state.full = true;
      var cb = document.getElementById('domainRangeInput');
      if (cb) cb.checked = true;
      drawStatic();
    }
    drawDynamic();
  }

  window.update_angle = function (v) { setAngle(v, true); };

  window.toggle_domainRange = function (on) {
    state.full = !!on;
    drawStatic();
    drawDynamic();
  };

  // sweep animation
  var rafId = null, u = 0, last = 0;
  function frameStep(now) {
    if (!state.sweeping) return;
    var dt = Math.min(60, now - last); last = now;
    u += dt / 3000;
    if (u > 1.22) u = 0;
    setAngle(Math.min(u, 1) * PI / 2);
    rafId = requestAnimationFrame(frameStep);
  }
  function startSweep() {
    if (state.sweeping) return;
    state.sweeping = true; u = 0; last = performance.now();
    var b = document.getElementById('quarterSweepInput');
    if (b) { b.textContent = '⏸ Pause sweep'; b.classList.add('active'); }
    rafId = requestAnimationFrame(frameStep);
  }
  function stopSweep() {
    state.sweeping = false;
    if (rafId) cancelAnimationFrame(rafId);
    rafId = null;
    var b = document.getElementById('quarterSweepInput');
    if (b) { b.textContent = '▶ Sweep 0 → π/2 and trace'; b.classList.remove('active'); }
  }
  window.trigger_quarterSweep = function () { state.sweeping ? stopSweep() : startSweep(); };

  // ---------- demo steps ----------
  var STEPS = [
    { title: 'One angle, two pictures',
      narration: 'At x = π/6 the radius points up and to the right; the teal connector carries the circle point\u2019s height straight across to the graph, where the curve sits at exactly that height above π/6.',
      angle: 0.524, full: false, sweep: false },
    { title: 'Climbing through the special angles',
      narration: 'Drag on to π/4 and then π/3: the point rises on the circle and the tracer rises on the graph in step, with the dashed orange drop lines landing on the matching tick marks.',
      angle: 1.047, full: false, sweep: false },
    { title: 'The peak at π/2',
      narration: 'At π/2 the radius points straight up, the circle point\u2019s height equals the full radius of 1, and the sine curve reaches its maximum value of 1.',
      angle: 1.5708, full: false, sweep: false },
    { title: 'Watch the record being written',
      narration: 'Play the quarter-turn sweep: the radius rotates from 0 to π/2 while the blue curve is drawn from the origin to the peak, one height at a time.',
      angle: 0, full: false, sweep: true },
    { title: 'Past the peak: sign follows quadrant',
      narration: 'Open the view to a full revolution and drag into the third quadrant: the circle point drops below the horizontal axis and the curve dips below the x-axis by exactly the same amount.',
      angle: 3.665, full: true, sweep: false }
  ];
  var stepIdx = 0;

  function applyStep(i) {
    stepIdx = (i + STEPS.length) % STEPS.length;
    var s = STEPS[stepIdx];
    stopSweep();
    var cb = document.getElementById('domainRangeInput');
    if (cb) cb.checked = s.full;
    state.full = s.full;
    drawStatic();
    setAngle(s.angle);
    if (s.sweep) startSweep();
    var n = document.getElementById('demoNarration');
    if (n) n.innerHTML = '<b>' + s.title + '.</b> ' + s.narration;
    var l = document.getElementById('stepLabel');
    if (l) l.textContent = 'Step ' + (stepIdx + 1) + ' / ' + STEPS.length;
  }
  window.nextStep = function () { applyStep(stepIdx + 1); };
  window.prevStep = function () { applyStep(stepIdx - 1); };

  // ---------- init ----------
  drawStatic();
  drawDynamic();
  applyStep(0);

  window.__markRendered();
})();
// @FIGURE_CODE_END

