      angle: 0.524, full: false, sweep: false },
    { title: 'Climbing through the special angles',
      narration: 'On to \u03c0/3: the point rises on the circle and the tracer rises on the graph in step, with the dashed orange drop lines landing on the matching tick marks.',
      angle: 1.047, full: false, sweep: false },
    { title: 'The peak at \u03c0/2',
      narration: 'At \u03c0/2 the radius points straight up, the circle point\u2019s height equals the full radius of 1, and the sine curve reaches its maximum value of 1.',
      angle: 1.5708, full: false, sweep: false },
    { title: 'Watch the record being written',
      narration: 'The quarter-turn sweep is playing: the radius rotates from 0 to \u03c0/2 while the blue curve is drawn from the origin to the peak, one height at a time.',
      angle: 0, full: false, sweep: true },
    { title: 'Past the peak: sign follows quadrant',
      narration: 'Opened to a full revolution, in the third quadrant: the circle point sits below the horizontal axis and the curve dips below the x-axis by exactly the same amount.',
      angle: 3.665, full: true, sweep: false }
  ];
  var stepIdx = 0;

  function applyStep(i) {
    stepIdx = (i + STEPS.length) % STEPS.length;
    var s = STEPS[stepIdx];
    stopSweep();
    var cb = document.getElementById('domainRangeInput');
    if (cb) cb.checked = s.full;
    state.full = s.full;
    applyViewbox();
    drawStatic();
    setAngle(s.angle);
    if (s.sweep) startSweep();
    var n = document.getElementById('demoNarration');
    if (n) n.innerHTML = '<b>' + s.title + '.</b> ' + s.narration;
    var l = document.getElementById('stepLabel');
    if (l) l.textContent = 'Step ' + (stepIdx + 1) + ' / ' + STEPS.length;
  }
  window.nextStep = function () { applyStep(stepIdx + 1); };
  window.prevStep = function () { applyStep(stepIdx - 1); };

  // ---------- init ----------
  applyViewbox();
  drawStatic();
  drawDynamic();
  applyStep(0);

  window.__markRendered();
})();
// @FIGURE_CODE_END

