// @FIGURE_CODE_BEGIN
(function () {
  var PI = Math.PI;
  var NAVY = '#1b3a63', BLUE = '#2e74b5', ORANGE = '#e8792a', TEAL = '#18988c',
      GRAYC = '#b6b6b6', GRAYF = '#bfbfbf', GRAYAX = '#a8a8a8', BLACK = '#000';

  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');

  // ---- shared vertical scale: circle radius R  ==  y = 1 on the graph ----
  var CCX = 115, CCY = 165, R = 70;
  var GX0 = 300, GY0 = 165, SX = 92, SY = 70;

  function gX(x) { return GX0 + x * SX; }
  function gY(y) { return GY0 - y * SY; }
  function cX(u) { return CCX + u * R; }
  function cY(v) { return CCY - v * R; }

  draw.rect(3000, 3000).move(-800, -800).fill('#ffffff');
  var st = draw.group();   // static geometry (the textbook figure)
  var dyn = draw.group();  // moving parts (revealed on first interaction)

  var state = { angle: 0.524, full: false, sweeping: false, revealed: false };

  function applyViewbox() {
    draw.viewbox(8, 34, state.full ? 925 : 580, 252);
  }

  // ---------- helpers ----------
  function txt(g, s, x, y, o) {
    o = o || {};
    var t = g.plain(s);
    t.font({
      family: o.family || 'Georgia, "Times New Roman", serif',
      size: o.size || 13,
      anchor: o.anchor || 'middle',
      style: o.italic ? 'italic' : 'normal',
      weight: o.weight || 'normal'
    });
    t.fill(o.color || BLACK);
    t.attr({ x: x, y: y });
    if (o.halo !== false) {
      t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': (o.haloW || 3.4), 'stroke-linejoin': 'round' });
    }
    return t;
  }

  function head(g, x, y, ang, size, color) {
    var p = [
      [x, y],
      [x - size * Math.cos(ang - 0.42), y - size * Math.sin(ang - 0.42)],
      [x - size * Math.cos(ang + 0.42), y - size * Math.sin(ang + 0.42)]
    ];
    return g.polygon(p).fill(color).stroke('none');
  }

  function dblArrow(g, x1, y1, x2, y2, color, w, sz) {
    w = w || 1.3; sz = sz || 7;
    g.line(x1, y1, x2, y2).stroke({ color: color, width: w, linecap: 'round' });
    var a = Math.atan2(y2 - y1, x2 - x1);
    head(g, x2, y2, a, sz, color);
    head(g, x1, y1, a + PI, sz, color);
  }

  function frac(g, x, yNum, num, den, size, color) {
    if (den === null) { txt(g, num, x, yNum + 9, { size: size, color: color }); return; }
    txt(g, num, x, yNum, { size: size, color: color });
    g.line(x - 6, yNum + 4, x + 6, yNum + 4).stroke({ color: color, width: 1 });
    txt(g, den, x, yNum + 18, { size: size, color: color });
  }

  function gcd(a, b) { return b ? gcd(b, a % b) : a; }
  function piFrac(a) {
    var n = Math.round(a / (PI / 12));
    if (Math.abs(a - n * PI / 12) > 0.025) return null;
    if (n === 0) return '0';
    var g = gcd(n, 12), num = n / g, den = 12 / g;
    var s = (num === 1 ? 'π' : num + 'π');
    return den === 1 ? s : s + '/' + den;
  }

  // default view is cropped just past the peak, like the textbook figure
  function curveDomain() { return state.full ? [-0.34, 2 * PI + 0.34] : [-0.50, 2.50]; }

  function sinePts(a, b, n) {
    var pts = [], i, x;
    n = n || 300;
    for (i = 0; i <= n; i++) { x = a + (b - a) * i / n; pts.push([gX(x), gY(Math.sin(x))]); }
    return pts;
  }

  // ---------- static drawing ----------
  function drawStatic() {
    st.clear();
    var axRight = state.full ? 905 : 555;

    // ===== LEFT PANEL : unit circle =====
    dblArrow(st, 18, CCY, 218, CCY, GRAYAX, 1.3, 7);
    dblArrow(st, CCX, 68, CCX, 262, GRAYAX, 1.3, 7);

    // gray spokes at the π/6 and π/4 families (drawn as full chords)
    [30, 45, 60, 120, 135, 150].forEach(function (d) {
      var a = d * PI / 180;
      st.line(cX(Math.cos(a)), cY(Math.sin(a)), cX(-Math.cos(a)), cY(-Math.sin(a)))
        .stroke({ color: GRAYF, width: 1.25 });
    });

    var circ = st.circle(2 * R).center(CCX, CCY).fill('none').stroke({ color: GRAYC, width: 1.7 });
    circ.css('cursor', 'pointer');
    circ.on('mousemove', function (e) { showTooltip('Unit circle: every point is (cos x, sin x)', e); })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('The unit circle',
            'A circle of radius 1 centred at the origin. Rotate by an angle x from the positive horizontal axis and the point you land on has coordinates (cos x, sin x). Its height above the horizontal axis IS sin x.');
        });

    // ===== RIGHT PANEL : axes =====
    dblArrow(st, 250, GY0, axRight, GY0, BLACK, 1.5, 8);
    st.line(GX0, 56, GX0, 268).stroke({ color: BLACK, width: 1.5 });
    head(st, GX0, 53, -PI / 2, 8, BLACK);
    txt(st, 'y', GX0 + 13, 50, { size: 19, italic: true, weight: 'bold' });
    txt(st, 'x', axRight + 14, GY0 + 6, { size: 19, italic: true, weight: 'bold' });

    // y ticks
    st.line(GX0 - 5, gY(1), GX0 + 5, gY(1)).stroke({ color: BLACK, width: 1.3 });
    st.line(GX0 - 5, gY(-1), GX0 + 5, gY(-1)).stroke({ color: BLACK, width: 1.3 });
    txt(st, '1', GX0 - 12, gY(1) + 5, { size: 15, anchor: 'end' });
    txt(st, '-1', GX0 - 12, gY(-1) + 5, { size: 15, anchor: 'end' });
    // origin label sits above-left of the origin, clear of the curve's left tail
    txt(st, '0', GX0 - 11, GY0 - 6, { size: 15, anchor: 'end' });

    // x ticks depend on mode
    var ticks = state.full
      ? [{ v: PI / 2, n: 'π', d: '2' }, { v: PI, n: 'π', d: null },
         { v: 3 * PI / 2, n: '3π', d: '2' }, { v: 2 * PI, n: '2π', d: null }]
      : [{ v: PI / 6, n: 'π', d: '6' }, { v: PI / 4, n: 'π', d: '4' },
         { v: PI / 3, n: 'π', d: '3' }, { v: PI / 2, n: 'π', d: '2' }];

    ticks.forEach(function (t, i) {
      var x = gX(t.v);
      st.line(x, GY0 - 5, x, GY0 + 5).stroke({ color: BLACK, width: 1.2 });
      // slight stagger of the middle fraction keeps π/6 · π/4 · π/3 from merging
      var yNum = (!state.full && i === 1) ? 205 : 186;
      if (!state.full && i === 1) {
        st.line(x, GY0 + 7, x, yNum - 10).stroke({ color: '#9a9a9a', width: 0.8 });
      }
      frac(st, x, yNum, t.n, t.d, 14, BLACK);
    });

    // orange dashed drops from curve to the labelled ticks
    ticks.forEach(function (t) {
      var s = Math.sin(t.v);
      if (Math.abs(s) < 0.06) return;
      var x = gX(t.v);
      var ln = st.line(x, gY(s), x, GY0).stroke({ color: ORANGE, width: 1.5, dasharray: '4,3' });
      ln.css('cursor', 'pointer');
      ln.on('mousemove', function (e) { showTooltip('sin(' + (piFrac(t.v) || t.v.toFixed(2)) + ') = ' + s.toFixed(3), e); })
        .on('mouseleave', hideTooltip);
    });

    // teal dashed horizontals: circle height  ←→  curve height
    var tealAngles = state.full ? [PI / 2, 3 * PI / 2] : [PI / 6, PI / 4, PI / 3, PI / 2];
    tealAngles.forEach(function (a) {
      var s = Math.sin(a), c = Math.cos(a);
      var y = gY(s);
      var ln = st.line(cX(c), y, gX(a), y).stroke({ color: TEAL, width: 1.5, dasharray: '5,4' });
      st.circle(3.6).center(cX(c), cY(s)).fill(TEAL).opacity(0.8);
      ln.css('cursor', 'pointer');
      ln.on('mousemove', function (e) {
        showTooltip('Height ' + s.toFixed(3) + ' on the circle = height of the curve at x = ' + (piFrac(a) || a.toFixed(2)), e);
      }).on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('Carrying the height across',
            'This teal line transports the circle point&rsquo;s vertical height straight across to the graph. The sine curve sits at exactly that height above the matching angle on the x-axis — the two pictures record the same number.');
        });
    });

    // ===== sine curve =====
    var dm = curveDomain();
    var pts = sinePts(dm[0], dm[1]);
    var curve = st.polyline(pts).fill('none')
      .stroke({ color: NAVY, width: 3.2, linecap: 'round', linejoin: 'round' });
    var p0 = pts[0], p1 = pts[1], pn = pts[pts.length - 1], pm = pts[pts.length - 2];
    head(st, p0[0], p0[1], Math.atan2(p0[1] - p1[1], p0[0] - p1[0]), 9, NAVY);
    head(st, pn[0], pn[1], Math.atan2(pn[1] - pm[1], pn[0] - pm[0]), 9, NAVY);
    curve.css('cursor', 'pointer');
    curve.on('mousemove', function (e) { showTooltip('y = sin(x): the circle point&rsquo;s height, plotted against the angle', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('y = sin(x)',
          'Sweep the angle x around the unit circle and record, at each moment, how high the point is. Plotting that height against x traces this curve: zero at x = 0, a maximum of 1 at x = π/2, back to zero at π, and negative through the third and fourth quadrants.');
      });

    txt(st, 'y = sin(x)', state.full ? 560 : 468, 68,
      { size: 17, color: BLUE, italic: true, weight: 'bold' });
  }

  // ---------- dynamic drawing ----------
  function updateReadout() {
    var out = document.getElementById('angleReadout');
    if (!out) return;
    if (!state.revealed) {
      out.textContent = 'Move the slider (or press ▶) to bring\none angle to life on both pictures.';
      out.style.whiteSpace = 'pre';
      return;
    }
    var a = state.angle, s = Math.sin(a), f = piFrac(a);
    out.textContent = 'x = ' + a.toFixed(2) + ' rad' + (f ? '  (' + f + ')' : '') +
      '\nsin(x) = height = ' + s.toFixed(3);
    out.style.whiteSpace = 'pre';
  }

  function drawDynamic() {
    dyn.clear();
    updateReadout();
    if (!state.revealed) return;   // step 0 = the plain textbook figure

    var a = state.angle, s = Math.sin(a), c = Math.cos(a);
    var dm = curveDomain();
    var showTrace = state.sweeping || state.full;

    // swept sector + traced arc
    if (showTrace && a > 0.01) {
      var large = (a > PI) ? 1 : 0;
      dyn.path('M ' + CCX + ',' + CCY + ' L ' + cX(1) + ',' + cY(0) +
        ' A ' + R + ',' + R + ' 0 ' + large + ' 0 ' + cX(c) + ',' + cY(s) + ' Z')
        .fill({ color: s >= 0 ? BLUE : ORANGE, opacity: 0.09 }).stroke('none');
      dyn.path('M ' + cX(1) + ',' + cY(0) + ' A ' + R + ',' + R + ' 0 ' + large + ' 0 ' + cX(c) + ',' + cY(s))
        .fill('none').stroke({ color: BLUE, width: 2.4, opacity: 0.5, linecap: 'round' });
    }

    // traced portion of the curve — only while the record is being written
    if (state.sweeping && a > 0.01) {
      dyn.polyline(sinePts(0, Math.min(a, dm[1]), 200)).fill('none')
        .stroke({ color: BLUE, width: 4.6, opacity: 0.4, linecap: 'round', linejoin: 'round' });
    }

    // active radius + drop line + point
    dyn.line(CCX, CCY, cX(c), cY(s)).stroke({ color: NAVY, width: 2.8, linecap: 'round' });
    dyn.line(cX(c), cY(s), cX(c), CCY).stroke({ color: NAVY, width: 1, dasharray: '3,3' });
    var pt = dyn.circle(8).center(cX(c), cY(s)).fill(NAVY);
    pt.css('cursor', 'pointer');
    pt.on('mousemove', function (e) {
      showTooltip('(cos x, sin x) = (' + c.toFixed(2) + ', ' + s.toFixed(2) + ')', e);
    }).on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('The circle point',
          'Its horizontal coordinate is cos x and its vertical coordinate is sin x. Only the vertical one — the height — is what the sine graph records.');
      });

    // teal connector + tracer on the graph
    if (a >= dm[0] && a <= dm[1]) {
      var tl = dyn.line(cX(c), gY(s), gX(a), gY(s))
        .stroke({ color: TEAL, width: 2, dasharray: '6,4' });
      tl.css('cursor', 'pointer');
      tl.on('mousemove', function (e) { showTooltip('Same height on both pictures: ' + s.toFixed(3), e); })
        .on('mouseleave', hideTooltip);
      dyn.line(gX(a), gY(s), gX(a), GY0).stroke({ color: NAVY, width: 1, dasharray: '3,3' });
      var tr = dyn.circle(9).center(gX(a), gY(s)).fill(NAVY).stroke({ color: '#fff', width: 1.3 });
      tr.css('cursor', 'pointer');
      tr.on('mousemove', function (e) {
        showTooltip('(x, sin x) = (' + a.toFixed(2) + ', ' + s.toFixed(2) + ')', e);
      }).on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('The graph point',
            'Its horizontal position is the angle x and its vertical position is the height of the circle point. Move the slider and watch both dots rise and fall together.');
        });
    }
  }

  // ---------- controls ----------
  function setAngle(v, fromUI) {
    state.angle = v;
    var inp = document.getElementById('angleInput');
    var out = document.getElementById('angleVal');
    if (inp && !fromUI) inp.value = v;
    if (out) out.value = (+v).toFixed(2);
    if (v > 2.45 && !state.full) {
      state.full = true;
      var cb = document.getElementById('domainRangeInput');
      if (cb) cb.checked = true;
      applyViewbox();
      drawStatic();
    }
    drawDynamic();
  }

  window.update_angle = function (v) { state.revealed = true; setAngle(v, true); };

