      angle: 3.665, full: true, sweep: false }
  ];
  var stepIdx = 0;

  function applyStep(i) {
    stepIdx = (i + STEPS.length) % STEPS.length;
    var s = STEPS[stepIdx];
    stopSweep();
    var cb = document.getElementById('domainRangeInput');
    if (cb) cb.checked = s.full;
    state.full = s.full;
    applyViewbox();
    drawStatic();
    setAngle(s.angle);
